async def run_import(dry_run=True):
    """Run the import with UPDATE and CREATE operations"""
    
    mongo_url = os.environ.get('MONGO_URL')
    db_name = os.environ.get('DB_NAME', 'test_database')
    
    client = AsyncIOMotorClient(mongo_url)
    db = client[db_name]
    
    mode = "DRY RUN" if dry_run else "APPLYING"
    print(f"\n{'='*60}")
    print(f" {mode} - Batch 3A Revised Import")
    print(f"{'='*60}")
    
    total_updates = 0
    total_creates = 0
    update_errors = 0
    create_ready = 0
    
    for book_data in BOOKS_DATA:
        book_title = book_data["title"]
        book_id = book_data["book_id"]
        
        print(f"\n📚 {book_title}")
        print(f"   Book ID: {book_id}")
        
        # Verify book exists
        book = await db.books.find_one({"id": book_id})
        if not book:
            print(f"   ❌ ERROR: Book not found in database!")
            continue
        
        updates_in_book = 0
        creates_in_book = 0
        
        for page_data in book_data["pages"]:
            page_num = page_data["page_number"]
            operation = page_data["operation"]
            text = page_data["text"]
            
            if operation == "UPDATE":
                page_id = page_data["page_id"]
                # Verify page exists
                existing_page = await db.pages.find_one({"id": page_id})
                if existing_page:
                    current_len = len(existing_page.get("text_content", ""))
                    new_len = len(text)
                    if dry_run:
                        print(f"   ✅ Page {page_num} UPDATE: {page_id[:8]}... ({current_len} → {new_len} chars)")
                    else:
                        # Actually update
                        await db.pages.update_one(
                            {"id": page_id},
                            {"$set": {"text_content": text}}
                        )
                        print(f"   ✅ Page {page_num} UPDATED: {current_len} → {new_len} chars")
                    updates_in_book += 1
                    total_updates += 1
                else:
                    print(f"   ❌ Page {page_num} UPDATE FAILED: Page ID {page_id} not found!")
                    update_errors += 1
                    
            elif operation == "CREATE":
                if dry_run:
                    print(f"   🆕 Page {page_num} CREATE: {len(text)} chars")
                    creates_in_book += 1
                    create_ready += 1
                else:
                    # Create new page
                    new_page_id = str(uuid.uuid4())
                    new_page = {
                        "id": new_page_id,
                        "book_id": book_id,
                        "page_number": page_num,
                        "text_content": text,
                        "image_url": None,
                        "audio_url": None,
                        "created_at": datetime.now(timezone.utc).isoformat(),
                        "updated_at": datetime.now(timezone.utc).isoformat()
                    }
                    await db.pages.insert_one(new_page)
                    
                    # Also add to book's embedded pages array
                    await db.books.update_one(
                        {"id": book_id},
                        {"$push": {"pages": {
                            "id": new_page_id,
                            "page_number": page_num,
                            "text_content": text,
                            "image_url": None,
                            "audio_url": None
                        }}}
                    )
                    print(f"   🆕 Page {page_num} CREATED: {new_page_id[:8]}... ({len(text)} chars)")
                    creates_in_book += 1
                    total_creates += 1
        
        print(f"   Summary: {updates_in_book} updates, {creates_in_book} creates")
    
    print(f"\n{'='*60}")
    print(f" {mode} SUMMARY")
    print(f"{'='*60}")
    
    if dry_run:
        print(f" ✅ UPDATE operations verified: {total_updates} pages")
        print(f" 🆕 CREATE operations ready: {create_ready} pages")
        print(f" ❌ Errors: {update_errors}")
        print(f"\n Total pages to process: {total_updates + create_ready}")
        if update_errors == 0:
            print(f"\n ✅ All {total_updates} Page IDs matched!")
            print(f" ✅ All {create_ready} new pages ready to create!")
    else:
        print(f" ✅ Pages UPDATED: {total_updates}")
        print(f" 🆕 Pages CREATED: {total_creates}")
        print(f" ❌ Errors: {update_errors}")
        print(f"\n Total pages processed: {total_updates + total_creates}")
    
    print(f"{'='*60}\n")
    
    client.close()
    return update_errors == 0


if __name__ == "__main__":
    dry_run = "--apply" not in sys.argv
    asyncio.run(run_import(dry_run))
